// Build search queries: top 2 keywords × top 2 locations
const profile   = $input.first().json;
const keywords  = (profile.searchKeywords || ['Software Engineer']).slice(0, 2);
const locations = (profile.locations || ['Bengaluru']).slice(0, 2);
const topSkills = (profile.skills || []).slice(0, 2);

const queries = [];
for (const keyword of keywords) {
  for (const location of locations) {
    if (queries.length >= 4) break;
    queries.push({ keyword, location, skillSuffix: topSkills.join(' ') });
  }
}

if (!queries.length) queries.push({ keyword: 'Software Engineer', location: 'India', skillSuffix: '' });

return queries.map(q => ({ json: { ...q, profile } }));

// Collect all raw jobs from SerpAPI and Naukri responses
const allItems = $input.all();

let rawJobs = [];
let profile = null;

for (const item of allItems) {
  const d = item.json;
  // SerpAPI response
  if (d.jobs_results) {
    for (const j of d.jobs_results) {
      const link = j.apply_options?.[0]?.link || j.share_link || '#';
      let src = 'gg';
      if (link.includes('linkedin.com')) src = 'li';
      else if (link.includes('glassdoor')) src = 'gd';
      else if (link.includes('naukri.com')) src = 'kn';
      rawJobs.push({
        title:   j.title || '',
        co:      j.company_name || '',
        loc:     j.location || '',
        sal:     j.detected_extensions?.salary || '',
        src,
        date:    j.detected_extensions?.posted_at || 'Recent',
        excerpt: (j.description || '').substring(0, 220),
        url:     link
      });
    }
  }
  // Naukri response
  if (d.jobDetails) {
    for (const j of d.jobDetails) {
      rawJobs.push({
        title:   j.title || '',
        co:      j.companyName || '',
        loc:     j.placeholders?.find(p => p.type === 'location')?.label || '',
        sal:     j.placeholders?.find(p => p.type === 'salary')?.label || '',
        src:     'kn',
        date:    j.footerPlaceholderLabel || 'Recent',
        excerpt: (j.jobDescription || '').replace(/<[^>]+>/g, '').substring(0, 220),
        url:     j.jdURL || '#'
      });
    }
  }
  // Carry profile forward
  if (d.profile) profile = d.profile;
  if (d.searchKeywords) profile = d; // profile IS the item
}

// Deduplicate
const seen = new Set();
rawJobs = rawJobs.filter(j => {
  const key = `${j.title.toLowerCase().trim()}|${j.co.toLowerCase().trim()}`;
  if (seen.has(key)) return false;
  seen.add(key); return true;
});

if (!profile) profile = $('Build Search Queries').first().json.profile || {};

return [{ json: { rawJobs, profile } }];

const { rawJobs, profile } = $input.first().json;

const skillWords      = (profile.skills || []).map(s => s.toLowerCase()).filter(w => w.length > 2);
const titleKeywords   = (profile.searchKeywords || []).map(k => k.toLowerCase());
const seniorityBoost  = (profile.seniorityKeywords || []).map(w => w.toLowerCase());
const avoidWords      = (profile.avoidKeywords || []).map(w => w.toLowerCase());
const expYears        = profile.yearsExperience || 0;

const crossDomainPenalty = ['sales executive','business development','relationship manager',
  'field sales','telecaller','insurance advisor','loan officer','marketing executive',
  'hr executive','content writer','seo executive','accountant','chartered accountant'];
const overqualified = ['intern','internship','trainee','apprentice','fresher','entry level','entry-level'];
const underqualified = ['vp ','vice president','chief ','director of','head of','managing director'];

const techDomains = ['software','engineering','frontend','backend','fullstack','devops',
  'data','ml','ai','product','design','analytics','cloud','mobile','security'];
const isTech = techDomains.some(d =>
  (profile.domain || '').toLowerCase().includes(d) ||
  skillWords.some(s => s.includes(d))
);

const scored = rawJobs.map(j => {
  const titleL = (j.title || '').toLowerCase();
  const fullTxt = `${j.title} ${j.excerpt}`.toLowerCase();
  let score = 20;

  // Title keyword match
  let titleMatched = false;
  for (const kw of titleKeywords) {
    const kwWords = kw.split(/\s+/).filter(w => w.length > 2);
    const matched = kwWords.filter(w => titleL.includes(w));
    if (matched.length >= Math.ceil(kwWords.length * 0.6)) { score += 30; titleMatched = true; break; }
  }

  // Skill matches
  let skillMatches = 0;
  for (const s of skillWords) if (fullTxt.includes(s)) skillMatches++;
  if (skillMatches >= 1) score += Math.min(skillMatches * 5, 25);

  // Seniority alignment
  for (const w of seniorityBoost) if (titleL.includes(w)) { score += 8; break; }

  // Cross-domain penalty
  if (isTech) for (const w of crossDomainPenalty) if (titleL.includes(w)) { score -= 40; break; }

  // Seniority mismatch
  if (expYears >= 4) for (const w of [...avoidWords, ...overqualified]) if (titleL.includes(w)) { score -= 25; break; }
  if (expYears <= 3) for (const w of underqualified) if (titleL.includes(w)) { score -= 15; break; }

  if (!titleMatched && skillMatches === 0) score -= 25;

  return { ...j, match: Math.min(Math.max(score, 5), 99) };
});

const relevant = scored.filter(j => j.match >= 45);
const results  = (relevant.length >= 3 ? relevant : scored.filter(j => j.match >= 30))
  .sort((a, b) => b.match - a.match)
  .slice(0, 10)
  .map((j, i) => ({ ...j, id: i + 1 }));

return [{ json: { jobs: results, profile } }];
